import socket
from ipaddress import IPv4Network
from threading import Thread


def task_func(ip_range, port):
    """
    Scan an IPv4 network range and report whether a TCP port is open on each host.

    Args:
        ip_range: An IPv4Network instance or a string like "192.168.1.0/24".
        port: TCP port number to test.

    Returns:
        dict: Mapping of IP address strings to booleans.
    """
    try:
        network = ip_range if isinstance(ip_range, IPv4Network) else IPv4Network(ip_range, strict=False)
    except Exception as exc:
        raise ValueError("ip_range must be a valid IPv4 network or network string") from exc

    try:
        port = int(port)
    except Exception as exc:
        raise ValueError("port must be an integer") from exc

    if not 1 <= port <= 65535:
        raise ValueError("port must be in the range 1-65535")

    results = {}

    def check_ip(ip_address):
        is_open = False
        try:
            with socket.socket(socket.AF_INET, socket.SOCK_STREAM) as sock:
                sock.settimeout(0.5)
                is_open = sock.connect_ex((ip_address, port)) == 0
        except OSError:
            is_open = False
        results[ip_address] = is_open

    hosts = [str(ip) for ip in network.hosts()]
    if not hosts:
        return {}

    max_threads = 128
    for start in range(0, len(hosts), max_threads):
        batch = hosts[start:start + max_threads]
        threads = []
        for ip_address in batch:
            thread = Thread(target=check_ip, args=(ip_address,))
            thread.start()
            threads.append(thread)
        for thread in threads:
            thread.join()

    return results
